//! OpenTelemetry ResourceLogs Protobuf Models & Serializer (`otlp_log_shipper::proto::model`).
//!
//! # Mechanism of Operation
//! - **Standard Protobuf Models**: Provides Prost-compatible struct representations of the
//!   OpenTelemetry Log Data Model (`opentelemetry.proto.logs.v1`).
//! - **Startup Wire Pre-Baking**: Utilized by `OtlpProtoWireEnvelope::new()` to bake static
//!   Resource and InstrumentationScope wire payloads once at system startup.
//! - **Decoding & Compliance Verification**: Utilized by integration and unit tests to verify
//!   that wire payloads generated by `OtlpProtoWireEnvelope` decode into 100% standard-compliant
//!   OpenTelemetry log records.

use prost::Message;
use std::sync::Arc;
use velda_observability::{AccessLogRecord, LogGrpcStatus, LogHttpMethod, UaFamily, UaOs};

use super::super::lut::{fast_write_hex32, fast_write_ip};

/// Root export request for OpenTelemetry Logs Service.
#[derive(Clone, PartialEq, Message)]
pub struct ExportLogsServiceRequest {
    #[prost(message, repeated, tag = "1")]
    pub resource_logs: Vec<ResourceLogs>,
}

#[derive(Clone, PartialEq, Message)]
pub struct ResourceLogs {
    #[prost(message, optional, tag = "1")]
    pub resource: Option<Resource>,
    #[prost(message, repeated, tag = "2")]
    pub scope_logs: Vec<ScopeLogs>,
    #[prost(string, tag = "3")]
    pub schema_url: String,
}

#[derive(Clone, PartialEq, Message)]
pub struct Resource {
    #[prost(message, repeated, tag = "1")]
    pub attributes: Vec<KeyValue>,
    #[prost(uint32, tag = "2")]
    pub dropped_attributes_count: u32,
}

#[derive(Clone, PartialEq, Message)]
pub struct ScopeLogs {
    #[prost(message, optional, tag = "1")]
    pub scope: Option<InstrumentationScope>,
    #[prost(message, repeated, tag = "2")]
    pub log_records: Vec<LogRecord>,
    #[prost(string, tag = "3")]
    pub schema_url: String,
}

#[derive(Clone, PartialEq, Message)]
pub struct InstrumentationScope {
    #[prost(string, tag = "1")]
    pub name: String,
    #[prost(string, tag = "2")]
    pub version: String,
    #[prost(message, repeated, tag = "3")]
    pub attributes: Vec<KeyValue>,
    #[prost(uint32, tag = "4")]
    pub dropped_attributes_count: u32,
}

#[derive(Clone, PartialEq, Message)]
pub struct LogRecord {
    #[prost(fixed64, tag = "1")]
    pub time_unix_nano: u64,
    #[prost(fixed64, tag = "11")]
    pub observed_time_unix_nano: u64,
    #[prost(int32, tag = "2")]
    pub severity_number: i32,
    #[prost(string, tag = "3")]
    pub severity_text: String,
    #[prost(message, optional, tag = "5")]
    pub body: Option<AnyValue>,
    #[prost(message, repeated, tag = "6")]
    pub attributes: Vec<KeyValue>,
    #[prost(uint32, tag = "7")]
    pub dropped_attributes_count: u32,
    #[prost(fixed32, tag = "8")]
    pub flags: u32,
    #[prost(bytes = "vec", tag = "9")]
    pub trace_id: Vec<u8>,
    #[prost(bytes = "vec", tag = "10")]
    pub span_id: Vec<u8>,
}

#[derive(Clone, PartialEq, Message)]
pub struct KeyValue {
    #[prost(string, tag = "1")]
    pub key: String,
    #[prost(message, optional, tag = "2")]
    pub value: Option<AnyValue>,
}

#[derive(Clone, PartialEq, Message)]
pub struct AnyValue {
    #[prost(oneof = "any_value::Value", tags = "1, 2, 3, 4, 5, 6, 7")]
    pub value: Option<any_value::Value>,
}

pub mod any_value {
    use prost::Oneof;

    #[derive(Clone, PartialEq, Oneof)]
    pub enum Value {
        #[prost(string, tag = "1")]
        StringValue(String),
        #[prost(bool, tag = "2")]
        BoolValue(bool),
        #[prost(int64, tag = "3")]
        IntValue(i64),
        #[prost(double, tag = "4")]
        DoubleValue(f64),
        #[prost(bytes = "vec", tag = "7")]
        BytesValue(Vec<u8>),
    }
}

impl KeyValue {
    #[inline(always)]
    pub fn string(key: impl Into<String>, val: impl Into<String>) -> Self {
        Self {
            key: key.into(),
            value: Some(AnyValue {
                value: Some(any_value::Value::StringValue(val.into())),
            }),
        }
    }

    #[inline(always)]
    pub fn int(key: impl Into<String>, val: i64) -> Self {
        Self {
            key: key.into(),
            value: Some(AnyValue {
                value: Some(any_value::Value::IntValue(val)),
            }),
        }
    }
}

impl LogRecord {
    /// Pre-allocates a reusable LogRecord template with pre-sized string buffers and 14 attribute slots.
    pub fn template() -> Self {
        let mut body_str = String::with_capacity(32);
        body_str.push_str("HTTP access log");

        let mut req_id_str = String::with_capacity(32);
        req_id_str.push_str("00000000000000000000000000000000");

        let mut ip_str = String::with_capacity(40);
        ip_str.push_str("0.0.0.0");

        let attributes = vec![
            KeyValue {
                key: "request_id".to_string(),
                value: Some(AnyValue {
                    value: Some(any_value::Value::StringValue(req_id_str)),
                }),
            },
            KeyValue::string("downstream_protocol", "http/1.1"),
            KeyValue::string("upstream_protocol", "http/1.1"),
            KeyValue::string("http.request.method", "GET"),
            KeyValue::int("http.response.status_code", 200),
            KeyValue::string("rpc.grpc.status_code", "0"),
            KeyValue::int("duration_ns", 0),
            KeyValue::int("http.response.body.size", 0),
            KeyValue::int("http.request.body.size", 0),
            KeyValue::int("velda.route_id", 0),
            KeyValue {
                key: "client.address".to_string(),
                value: Some(AnyValue {
                    value: Some(any_value::Value::StringValue(ip_str)),
                }),
            },
            KeyValue::int("client.port", 0),
            KeyValue::string("user_agent.family", "Unknown"),
            KeyValue::int("user_agent.major_version", 0),
            KeyValue::string("user_agent.os", "Unknown"),
        ];

        Self {
            time_unix_nano: 0,
            observed_time_unix_nano: 0,
            severity_number: 9,
            severity_text: String::with_capacity(8),
            body: Some(AnyValue {
                value: Some(any_value::Value::StringValue(body_str)),
            }),
            attributes,
            dropped_attributes_count: 0,
            flags: 0,
            trace_id: Vec::new(),
            span_id: Vec::new(),
        }
    }

    /// Mutates pre-allocated LogRecord template in-place from scalar [`AccessLogRecord`].
    pub fn populate_from_record(&mut self, rec: &AccessLogRecord) {
        let downstream_protocol = rec.downstream_protocol();
        let upstream_protocol = rec.upstream_protocol();
        let method = LogHttpMethod::from_u8(rec.method);
        let grpc_st = LogGrpcStatus::from_u8(rec.grpc_status);
        let ua_fam = UaFamily::from_u8(rec.ua_family);
        let ua_os = UaOs::from_u8(rec.ua_os);
        let ts_nano = (rec.timestamp_sec as u64).saturating_mul(1_000_000_000);

        let req_hi = rec.timestamp_sec as u64;
        let req_lo = rec.request_id;

        let (severity_num, severity_txt) = if rec.status_code >= 500
            || (grpc_st != LogGrpcStatus::Ok && grpc_st != LogGrpcStatus::NonGrpc)
        {
            (17, "ERROR")
        } else if rec.status_code >= 400 {
            (13, "WARN")
        } else {
            (9, "INFO")
        };

        // SIMD 128-bit dual-timestamp store on x86_64
        #[cfg(target_arch = "x86_64")]
        unsafe {
            use core::arch::x86_64::*;
            let ts_vec = _mm_set1_epi64x(ts_nano as i64);
            _mm_storeu_si128(&mut self.time_unix_nano as *mut u64 as *mut __m128i, ts_vec);
        }
        #[cfg(not(target_arch = "x86_64"))]
        {
            self.time_unix_nano = ts_nano;
            self.observed_time_unix_nano = ts_nano;
        }
        self.severity_number = severity_num;

        self.severity_text.clear();
        self.severity_text.push_str(severity_txt);

        // Body is constant "HTTP access log" (0 CPU cycles spent on dynamic body string formatting)
        if let Some(AnyValue {
            value: Some(any_value::Value::StringValue(ref mut s)),
        }) = self.body
            && s != "HTTP access log"
        {
            s.clear();
            s.push_str("HTTP access log");
        }

        self.trace_id.clear();
        self.span_id.clear();

        // Attribute updates
        if self.attributes.len() >= 15 {
            // request_id attribute (32-character hex string):
            if let Some(AnyValue {
                value: Some(any_value::Value::StringValue(ref mut s_req)),
            }) = self.attributes[0].value
            {
                let bytes = unsafe { s_req.as_mut_vec() };
                bytes.clear();
                fast_write_hex32(bytes, req_hi, req_lo);
            }

            if let Some(AnyValue {
                value: Some(any_value::Value::StringValue(ref mut s)),
            }) = self.attributes[1].value
            {
                s.clear();
                s.push_str(downstream_protocol.as_str());
            }

            if let Some(AnyValue {
                value: Some(any_value::Value::StringValue(ref mut s)),
            }) = self.attributes[2].value
            {
                s.clear();
                s.push_str(upstream_protocol.as_str());
            }

            if let Some(AnyValue {
                value: Some(any_value::Value::StringValue(ref mut s)),
            }) = self.attributes[3].value
            {
                s.clear();
                s.push_str(method.as_str());
            }

            if let Some(AnyValue {
                value: Some(any_value::Value::IntValue(ref mut v)),
            }) = self.attributes[4].value
            {
                *v = rec.status_code as i64;
            }

            if let Some(AnyValue {
                value: Some(any_value::Value::StringValue(ref mut s)),
            }) = self.attributes[5].value
            {
                s.clear();
                s.push_str(grpc_st.as_str());
            }

            if let Some(AnyValue {
                value: Some(any_value::Value::IntValue(ref mut v)),
            }) = self.attributes[6].value
            {
                *v = rec.duration_ns as i64;
            }

            if let Some(AnyValue {
                value: Some(any_value::Value::IntValue(ref mut v)),
            }) = self.attributes[7].value
            {
                *v = rec.bytes_tx as i64;
            }

            if let Some(AnyValue {
                value: Some(any_value::Value::IntValue(ref mut v)),
            }) = self.attributes[8].value
            {
                *v = rec.bytes_rx as i64;
            }

            if let Some(AnyValue {
                value: Some(any_value::Value::IntValue(ref mut v)),
            }) = self.attributes[9].value
            {
                *v = rec.route_id as i64;
            }

            if let Some(AnyValue {
                value: Some(any_value::Value::StringValue(ref mut s)),
            }) = self.attributes[10].value
            {
                let bytes = unsafe { s.as_mut_vec() };
                bytes.clear();
                fast_write_ip(bytes, rec.peer_ip);
            }

            if let Some(AnyValue {
                value: Some(any_value::Value::IntValue(ref mut v)),
            }) = self.attributes[11].value
            {
                *v = rec.peer_port as i64;
            }

            if let Some(AnyValue {
                value: Some(any_value::Value::StringValue(ref mut s)),
            }) = self.attributes[12].value
            {
                s.clear();
                s.push_str(ua_fam.as_str());
            }

            if let Some(AnyValue {
                value: Some(any_value::Value::IntValue(ref mut v)),
            }) = self.attributes[13].value
            {
                *v = rec.ua_major_version as i64;
            }

            if let Some(AnyValue {
                value: Some(any_value::Value::StringValue(ref mut s)),
            }) = self.attributes[14].value
            {
                s.clear();
                s.push_str(ua_os.as_str());
            }
        }
    }
}

/// Helper to format batches of [`AccessLogRecord`] into a Prost `ExportLogsServiceRequest`.
pub fn format_otlp_records_proto(
    batches: &[Arc<[AccessLogRecord]>],
    service_name: &str,
) -> (ExportLogsServiceRequest, usize) {
    let total_recs: usize = batches.iter().map(|b| b.len()).sum();
    let mut log_records = Vec::with_capacity(total_recs);

    for batch in batches {
        for rec in batch.iter() {
            let mut item = LogRecord::template();
            item.populate_from_record(rec);
            log_records.push(item);
        }
    }

    let req = ExportLogsServiceRequest {
        resource_logs: vec![ResourceLogs {
            resource: Some(Resource {
                attributes: vec![
                    KeyValue::string("service.name", service_name),
                    KeyValue::string("telemetry.sdk.name", "velda-edge"),
                    KeyValue::string("telemetry.sdk.language", "rust"),
                ],
                dropped_attributes_count: 0,
            }),
            scope_logs: vec![ScopeLogs {
                scope: Some(InstrumentationScope {
                    name: "velda.access_log".to_string(),
                    version: "0.1.0".to_string(),
                    attributes: Vec::new(),
                    dropped_attributes_count: 0,
                }),
                log_records,
                schema_url: "https://opentelemetry.io/schemas/1.26.0".to_string(),
            }],
            schema_url: "https://opentelemetry.io/schemas/1.26.0".to_string(),
        }],
    };

    (req, total_recs)
}
